import axios from "axios";

// ✅ Load token from localStorage on start
let token = localStorage.getItem("token");

// ✅ Set token (after login)
export const setAuthToken = (newToken) => {
  token = newToken;
  localStorage.setItem("token", newToken); // persist
};

// ✅ Optional: clear token (for logout)
export const clearAuthToken = () => {
  token = null;
  localStorage.removeItem("token");
};

// ✅ Axios instance
const API = axios.create({
  baseURL: "http://localhost:8080",
});

// ✅ INTERCEPTOR (ALWAYS attach latest token)
API.interceptors.request.use(
  (config) => {
    const storedToken = localStorage.getItem("token"); // always fresh

    if (storedToken) {
      config.headers.Authorization = `Bearer ${storedToken}`;
    }

    return config;
  },
  (error) => Promise.reject(error)
);

export default API;
